/* Lecture 14 Cardiovascular: user-supplied MCQs. Preserve wording, options, original answer key.
 * Separate from recall flashcards; flagged lecture claims require clinical verification. */
(function(){'use strict';const bank=[{"id":"pharm-e2-user-cardio14-mcq-001","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #1","q":"What is the primary mechanistic goal of medications used to improve cardiac contractility in congestive heart failure (CHF), according to the lecture?","options":["Decrease intracellular calcium concentrations","Increase intracellular calcium concentrations to improve cardiac muscle contraction","Inhibit all cardiac electrical impulses","Decrease actin-myosin interactions"],"answer":1,"why":"Cardiac contraction depends on calcium binding troponin C to allow actin–myosin interaction. Some inotropes increase intracellular calcium availability; pimobendan can also sensitize myofilaments to calcium. Greater contractility may improve output but also increase oxygen demand or arrhythmia risk.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":1,"originalImportedWhy":"Uploaded answer key: Increase intracellular calcium concentrations to improve cardiac muscle contraction","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-002","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #2","q":"Which ion is primarily responsible for facilitating actin-myosin interactions in cardiac muscle?","options":["Sodium","Potassium","Chloride","Calcium"],"answer":3,"why":"Uploaded answer key: Calcium","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":2},{"id":"pharm-e2-user-cardio14-mcq-003","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #3","q":"During the forward operation of the sodium-calcium exchanger, what occurs?","options":["Three Na⁺ ions enter the cell while one Ca²⁺ ion exits.","Three Na⁺ ions exit while one Ca²⁺ ion enters.","One Na⁺ ion enters while three Ca²⁺ ions exit.","Both sodium and calcium enter the cell."],"answer":0,"why":"Forward-mode NCX brings three sodium ions inward while extruding one calcium ion. This helps remove calcium after contraction; the sodium gradient is maintained in part by Na⁺/K⁺-ATPase.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":3,"originalImportedWhy":"Uploaded answer key: Three Na⁺ ions enter the cell while one Ca²⁺ ion exits.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-004","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #4","q":"During the reverse operation of the sodium-calcium exchanger, which movement occurs?","options":["Calcium exits while sodium enters.","Both ions exit the cell.","One Ca²⁺ enters while three Na⁺ exit.","Three Ca²⁺ enter while one Na⁺ exits."],"answer":2,"why":"Reversing the electrochemical driving force of NCX allows calcium entry in exchange for sodium exit. Transport direction depends on membrane potential and ion gradients.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":4,"originalImportedWhy":"Uploaded answer key: One Ca²⁺ enters while three Na⁺ exit.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-005","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #5","q":"Which membrane transport systems help maintain electrochemical balance in cardiac myocytes?","options":["Sodium channels exclusively","Na⁺/K⁺ ATPase, Ca²⁺ ATPase, and L-type voltage-gated calcium channels","Chloride transporters exclusively","Potassium channels without ATPases"],"answer":1,"why":"Uploaded answer key: Na⁺/K⁺ ATPase, Ca²⁺ ATPase, and L-type voltage-gated calcium channels","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":5},{"id":"pharm-e2-user-cardio14-mcq-006","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #6","q":"What is the primary molecular target of digoxin?","options":["Beta-1 adrenergic receptors","Phosphodiesterase 3","L-type calcium channels","Na⁺/K⁺ ATPase"],"answer":3,"why":"Digoxin inhibits the Na+/K+-ATPase pump, increasing intracellular sodium, reducing the gradient that normally drives calcium efflux through NCX, and increasing intracellular calcium for stronger contraction.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":6,"originalImportedQuestion":"What is the primary molecular target of digoxin?","originalImportedAnswer":"Na⁺/K⁺ ATPase","originalImportedWhy":"Uploaded answer key: Na⁺/K⁺ ATPase"},{"id":"pharm-e2-user-cardio14-mcq-007","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #7","q":"What happens to intracellular sodium concentrations following digoxin administration?","options":["Intracellular sodium increases.","Intracellular sodium decreases.","Sodium concentrations remain unchanged.","Sodium is converted into calcium."],"answer":0,"why":"Uploaded answer key: Intracellular sodium increases.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":7},{"id":"pharm-e2-user-cardio14-mcq-008","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #8","q":"How does increased intracellular sodium ultimately improve cardiac contraction during digoxin therapy?","options":["It directly inhibits troponin C.","It prevents calcium from entering the myocyte.","It reduces forward Na⁺/Ca²⁺ exchange and favors intracellular calcium accumulation.","It blocks all calcium channels."],"answer":2,"why":"Digoxin inhibits Na⁺/K⁺-ATPase, allowing intracellular Na⁺ to rise. Reduced sodium gradient decreases calcium extrusion through NCX, helping calcium accumulate in the sarcoplasmic reticulum for stronger contraction.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":8,"originalImportedWhy":"Uploaded answer key: It reduces forward Na⁺/Ca²⁺ exchange and favors intracellular calcium accumulation.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-009","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #9","q":"Which term describes the increased force of cardiac contraction produced by digoxin?","options":["Negative chronotropism","Positive inotropism","Negative dromotropism","Positive lusitropism"],"answer":1,"why":"Uploaded answer key: Positive inotropism","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":9},{"id":"pharm-e2-user-cardio14-mcq-010","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #10","q":"In the tension tracing on slide 5, what does the digoxin-treated curve demonstrate?","options":["Complete absence of contraction","Decreased calcium availability","Reduced myocardial tension","Increased myocardial tension associated with increased intracellular calcium"],"answer":3,"why":"Uploaded answer key: Increased myocardial tension associated with increased intracellular calcium","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":10},{"id":"pharm-e2-user-cardio14-mcq-011","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #11","q":"Which secondary effect of digoxin is described as negative chronotropism?","options":["Decreased heart rate","Increased heart rate","Increased ventricular conduction velocity","Increased blood pressure exclusively"],"answer":0,"why":"Digoxin increases vagal activity and reduces AV nodal conduction independently of its direct positive inotropic effect. Increased contractility does not automatically mean tachycardia.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":11,"originalImportedWhy":"Uploaded answer key: Decreased heart rate","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-012","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #12","q":"Why can digoxin slow the heart rate and AV nodal conduction while increasing cardiac contractility?","options":["It increases myocardial calcium availability through Na⁺/K⁺-ATPase inhibition while increasing vagal influence at the SA and AV nodes.","It directly destroys the SA node to lower heart rate.","It inhibits all sympathetic and parasympathetic neurons.","It permanently blocks ventricular L-type calcium channels."],"answer":0,"why":"Digoxin produces two clinically distinct effects: Na⁺/K⁺-ATPase inhibition raises intracellular calcium and inotropy; increased vagal influence slows SA rate and AV nodal conduction. It is misleading to attribute its negative chronotropy exclusively to improved cardiac output.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":12,"originalImportedQuestion":"According to the lecture, why can digoxin produce bradycardia despite improving cardiac contractility?","originalImportedAnswer":"Improved cardiac output stimulates vagal activity, increasing parasympathetic influence.","originalImportedWhy":"Uploaded answer key: Improved cardiac output stimulates vagal activity, increasing parasympathetic influence.","reviewFlag":"Corrected answer-option oversimplification about the digoxin vagal effect."},{"id":"pharm-e2-user-cardio14-mcq-013","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #13","q":"What does negative dromotropism describe?","options":["Increased myocardial contraction","Decreased conduction through the AV node","Increased ventricular filling pressure","Increased sympathetic stimulation"],"answer":1,"why":"Negative dromotropy means slower conduction, especially through the AV node, while negative chronotropy refers to reduced heart rate. Distinguishing these effects helps interpret antiarrhythmic actions.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":13,"originalImportedWhy":"Uploaded answer key: Decreased conduction through the AV node","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-014","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #14","q":"Which cardiac structure normally initiates the electrical impulses responsible for heart rate?","options":["AV node","Purkinje fibers","Ventricular myocardium","SA node"],"answer":3,"why":"Uploaded answer key: SA node","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":14},{"id":"pharm-e2-user-cardio14-mcq-015","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #15","q":"What may occur if electrical conduction through the AV node becomes completely blocked?","options":["The ventricles may generate a slower escape rhythm.","The SA node immediately stops functioning.","The ventricles contract faster than normal.","The heart becomes completely insensitive to calcium."],"answer":0,"why":"Complete AV block prevents impulses from reaching ventricles normally. An escape pacemaker may maintain a slower rhythm, but output and perfusion may be inadequate.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":15,"originalImportedWhy":"Uploaded answer key: The ventricles may generate a slower escape rhythm.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-016","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #16","q":"Which plant is historically associated with the development of digoxin?","options":["Oleander","Belladonna","Foxglove (Digitalis)","Yew"],"answer":2,"why":"Uploaded answer key: Foxglove (Digitalis)","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":16},{"id":"pharm-e2-user-cardio14-mcq-017","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #17","q":"Which naturally occurring cardiac glycoside is identified as an active ingredient of foxglove?","options":["Atropine","Digitoxin","Dopamine","Dobutamine"],"answer":1,"why":"Uploaded answer key: Digitoxin","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":17},{"id":"pharm-e2-user-cardio14-mcq-018","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #18","q":"Which adverse effect is associated with digoxin toxicity?","options":["Complete elimination of ventricular electrical activity without other changes","Bronchodilation exclusively","Increased skeletal muscle strength","Ventricular arrhythmias, AV block, and gastrointestinal disturbances"],"answer":3,"why":"Digoxin has a narrow safety margin. Excess Na⁺/K⁺-ATPase inhibition and altered calcium cycling can cause ectopy, AV block and nausea; kidney and potassium status affect risk.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":18,"originalImportedWhy":"Uploaded answer key: Ventricular arrhythmias, AV block, and gastrointestinal disturbances","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-019","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #19","q":"What does pulsus bigeminy refer to in the context of digoxin toxicity?","options":["A repeating pattern involving premature ventricular contractions","Complete absence of ventricular contractions","Persistent sinus bradycardia without ectopic beats","Normal sinus rhythm with increased contractility"],"answer":0,"why":"Uploaded answer key: A repeating pattern involving premature ventricular contractions","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":19},{"id":"pharm-e2-user-cardio14-mcq-020","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #20","q":"Which electrolyte abnormality increases susceptibility to digoxin-associated cardiovascular toxicity?","options":["Hypernatremia","Hyperchloremia","Hypokalemia","Hypermagnesemia"],"answer":2,"why":"Potassium and digoxin compete for interactions with Na+/K+-ATPase, so hypokalemia increases digoxin binding and arrhythmia risk. Monitor electrolytes, kidney function and rhythm; digoxin has a narrow therapeutic margin.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":20,"originalImportedQuestion":"Which electrolyte abnormality increases susceptibility to digoxin-associated cardiovascular toxicity?","originalImportedAnswer":"Hypokalemia","originalImportedWhy":"Uploaded answer key: Hypokalemia"},{"id":"pharm-e2-user-cardio14-mcq-021","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #21","q":"Why are patients receiving both digoxin and certain diuretics at increased risk for toxicity?","options":["Diuretics directly convert digoxin into a toxic metabolite.","Some diuretics produce hypokalemia, increasing susceptibility to digoxin toxicity.","Diuretics prevent digoxin from binding to cardiac tissue.","Diuretics always cause hypercalcemia."],"answer":1,"why":"Some loop/thiazide diuretics increase renal potassium loss. Hypokalemia increases sensitivity to digoxin's pump inhibition and makes dangerous dysrhythmias more likely.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":21,"originalImportedWhy":"Uploaded answer key: Some diuretics produce hypokalemia, increasing susceptibility to digoxin toxicity.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-022","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #22","q":"According to the lecture, which management approach is appropriate when digoxin-associated cardiovascular toxicity develops?","options":["Increase the digoxin dose.","Administer additional digoxin to stabilize contraction.","Discontinue all fluid therapy.","Discontinue digoxin, address arrhythmias, support renal clearance, and correct hypokalemia carefully when present."],"answer":3,"why":"Stop or reassess the causative drug, obtain an ECG/electrolytes/renal profile and stabilize the patient. Potassium correction should be deliberate because both low and high potassium can be dangerous.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":22,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources.","originalImportedWhy":"Uploaded answer key: Discontinue digoxin, address arrhythmias, support renal clearance, and correct hypokalemia carefully when present.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-023","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #23","q":"At clinically relevant inotropic doses, which receptor primarily mediates dopamine's increase in myocardial contractility?","options":["Beta-1 adrenergic receptor","Alpha-2 adrenergic receptor","Muscarinic receptor","Nicotinic receptor"],"answer":0,"why":"Dopamine produces dose-dependent effects. Its cardiac positive inotropy is mainly mediated by beta-1 adrenergic stimulation, increasing cAMP and calcium availability. D1 receptor stimulation primarily mediates vasodilation in selected vascular beds, not myocardial contractility.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":23,"reviewFlag":"Original uploaded key incorrectly identified D1 as the main inotropic receptor.","originalImportedQuestion":"According to the lecture, dopamine produces positive inotropic effects primarily through activation of which receptor?","originalImportedAnswer":"D1 dopamine receptor","originalImportedWhy":"Uploaded answer key: D1 dopamine receptor"},{"id":"pharm-e2-user-cardio14-mcq-024","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #24","q":"What occurs following activation of adenylyl cyclase in cardiac myocytes?","options":["ATP is converted into GMP.","cAMP is immediately destroyed.","ATP is converted into cAMP.","Calcium is removed from the myocardium."],"answer":2,"why":"Cardiac beta-1 stimulation couples through Gs to adenylyl cyclase, converting ATP to cAMP. PKA then alters calcium entry and cycling.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":24,"originalImportedWhy":"Uploaded answer key: ATP is converted into cAMP.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-025","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #25","q":"How does increased intracellular cAMP improve cardiac contractility?","options":["By inhibiting actin-myosin binding","By promoting calcium mobilization within the cardiac myocyte","By preventing calcium from binding to troponin","By inhibiting all adrenergic receptors"],"answer":1,"why":"cAMP-dependent protein kinase enhances calcium channel opening and sarcoplasmic-reticulum calcium cycling, increasing calcium availability for contraction. This may improve output but can raise arrhythmia risk.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":25,"originalImportedWhy":"Uploaded answer key: By promoting calcium mobilization within the cardiac myocyte","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-026","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #26","q":"Dopamine acts at dopaminergic and adrenergic receptors in a dose-dependent manner. Which interpretation is appropriate?","options":["D1 stimulation always produces the greatest increase in cardiac contraction.","Dopamine has identical effects at all infusion rates.","Only D2 receptors mediate dopamine-induced vasoconstriction.","D1 vascular effects and beta-1 cardiac effects must be distinguished; fixed D1:D2 affinity ratios do not determine a patient's clinical response."],"answer":3,"why":"Dose-dependent responses and receptor selectivity are more clinically useful than the unsupported fixed tenfold D1:D2 affinity comparison in the uploaded question.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":26,"reviewFlag":"Replaced unsupported tenfold receptor-affinity memorization with clinically useful mechanism.","originalImportedQuestion":"According to the lecture, dopamine has approximately how much greater affinity for D1 receptors than D2 receptors?","originalImportedAnswer":"Tenfold","originalImportedWhy":"Uploaded answer key: Tenfold"},{"id":"pharm-e2-user-cardio14-mcq-027","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #27","q":"What is the primary receptor target of dobutamine?","options":["Beta-1 adrenergic receptors","Alpha-1 adrenergic receptors","Muscarinic receptors","Angiotensin II receptors"],"answer":0,"why":"Uploaded answer key: Beta-1 adrenergic receptors","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":27},{"id":"pharm-e2-user-cardio14-mcq-028","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #28","q":"Which signaling pathway best describes the positive inotropic effects of dobutamine?","options":["Beta-1 inhibition → decreased cAMP → decreased calcium","Alpha-1 activation → decreased intracellular calcium","Beta-1 activation → increased adenylyl cyclase activity → increased cAMP → increased intracellular calcium","PDE5 inhibition → increased cGMP → reduced myocardial contraction"],"answer":2,"why":"Dobutamine predominantly activates cardiac beta-1 signaling, raising cAMP and intracellular calcium and producing inotropy. It is titrated in monitored patients rather than given as routine chronic outpatient therapy.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":28,"originalImportedWhy":"Uploaded answer key: Beta-1 activation → increased adenylyl cyclase activity → increased cAMP → increased intracellular calcium","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-029","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #29","q":"What is the mechanism of action of amrinone?","options":["Na⁺/K⁺ ATPase inhibition","Phosphodiesterase 3 inhibition","Beta-1 receptor antagonism","Angiotensin II receptor antagonism"],"answer":1,"why":"Uploaded answer key: Phosphodiesterase 3 inhibition","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":29},{"id":"pharm-e2-user-cardio14-mcq-030","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #30","q":"What reaction is normally catalyzed by phosphodiesterase 3?","options":["ATP → cAMP","GTP → cGMP","Angiotensin I → angiotensin II","cAMP → 5′-AMP"],"answer":3,"why":"PDE3 hydrolyzes cAMP to inactive 5′-AMP. Inhibiting it prolongs cAMP signaling in myocardium and vascular smooth muscle.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":30,"originalImportedWhy":"Uploaded answer key: cAMP → 5′-AMP","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-031","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #31","q":"What is the primary consequence of inhibiting PDE3 in cardiac myocytes?","options":["Increased cAMP, increased intracellular calcium, and increased contraction","Decreased cAMP and decreased contraction","Increased sodium excretion without myocardial effects","Direct inhibition of troponin C"],"answer":0,"why":"PDE3 inhibition prolongs cAMP/PKA signaling, enhancing myocardial calcium cycling. In vessels, the same cyclic-nucleotide change promotes smooth-muscle relaxation.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":31,"originalImportedWhy":"Uploaded answer key: Increased cAMP, increased intracellular calcium, and increased contraction","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-032","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #32","q":"Why is pimobendan classified as an inodilator?","options":["It exclusively produces vasoconstriction.","It reduces cardiac contractility while increasing blood pressure.","It produces positive inotropic effects and vasodilation.","It only blocks beta-1 receptors."],"answer":2,"why":"Pimobendan produces positive inotropy by sensitizing cardiac troponin C to calcium, and vasodilation mainly through PDE3 inhibition/increased cAMP in vascular smooth muscle. It is an inodilator rather than simply a calcium-loading drug.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":32,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources.","originalImportedQuestion":"Why is pimobendan classified as an inodilator?","originalImportedAnswer":"It produces positive inotropic effects and vasodilation.","originalImportedWhy":"Uploaded answer key: It produces positive inotropic effects and vasodilation."},{"id":"pharm-e2-user-cardio14-mcq-033","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #33","q":"Which combination best describes pimobendan's mechanism of action according to the lecture?","options":["Beta-1 blockade and Na⁺/K⁺ ATPase inhibition","PDE3 inhibition and calcium sensitization","PDE5 inhibition and alpha-1 activation","Angiotensin II receptor antagonism and sodium channel blockade"],"answer":1,"why":"Uploaded answer key: PDE3 inhibition and calcium sensitization","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":33},{"id":"pharm-e2-user-cardio14-mcq-034","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #34","q":"How does pimobendan increase calcium sensitivity in cardiac muscle?","options":["It permanently inhibits calcium entry.","It decreases troponin C expression.","It blocks all calcium-binding sites.","It increases the affinity of troponin C for calcium."],"answer":3,"why":"Pimobendan increases myofilament responsiveness to existing calcium through troponin C sensitization; unlike a pure beta-agonist, it need not rely entirely on increasing calcium influx.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":34,"originalImportedWhy":"Uploaded answer key: It increases the affinity of troponin C for calcium.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-035","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #35","q":"Which mechanism best explains pimobendan's vascular smooth-muscle relaxation?","options":["PDE3 inhibition increases cAMP and promotes vascular smooth-muscle relaxation.","Stimulation of alpha-1-mediated vascular contraction.","Blocking nitric oxide production.","Increasing vascular smooth-muscle calcium concentrations."],"answer":0,"why":"Pimobendan combines calcium sensitization in myocardium with PDE3 inhibition. In vascular smooth muscle, increased cAMP promotes relaxation and vasodilation. The lecture's potassium-channel explanation should not be treated as its defining clinical mechanism.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":35,"originalImportedQuestion":"According to the lecture, how does pimobendan produce vasodilation?","originalImportedAnswer":"Opening potassium channels in vascular smooth muscle, promoting relaxation","originalImportedWhy":"Uploaded answer key: Opening potassium channels in vascular smooth muscle, promoting relaxation"},{"id":"pharm-e2-user-cardio14-mcq-036","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #36","q":"According to the lecture, which species is specifically approved for pimobendan use?","options":["Cats","Horses","Dogs","All companion species equally"],"answer":2,"why":"Uploaded answer key: Dogs","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":36},{"id":"pharm-e2-user-cardio14-mcq-037","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #37","q":"Which adverse effect is identified in the lecture's study guide as a common concern among anti-CHF drugs?","options":["Corneal ulceration","Arrhythmias","Severe hypoglycemia","Urinary obstruction"],"answer":1,"why":"Uploaded answer key: Arrhythmias","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":37},{"id":"pharm-e2-user-cardio14-mcq-038","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #38","q":"Which mechanisms are identified as major causes of cardiac dysrhythmias?","options":["Increased gastrointestinal motility and decreased renal filtration","Decreased oxygen consumption exclusively","Increased myocardial calcium sensitivity exclusively","Abnormal impulse generation and re-entry conduction disturbances"],"answer":3,"why":"Abnormal automaticity or triggered beats can start an arrhythmia, while a re-entry circuit repeatedly propagates an impulse. Antiarrhythmics can change refractoriness and conduction in ways that help or worsen either mechanism.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":38,"originalImportedWhy":"Uploaded answer key: Abnormal impulse generation and re-entry conduction disturbances","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-039","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #39","q":"Which condition is classified as a supraventricular tachycardia in the lecture?","options":["Atrial fibrillation","Ventricular fibrillation","Ventricular tachycardia","Ventricular premature contraction"],"answer":0,"why":"Uploaded answer key: Atrial fibrillation","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":39},{"id":"pharm-e2-user-cardio14-mcq-040","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #40","q":"Which condition is classified as a ventricular arrhythmia?","options":["Atrial flutter","Sinus node dysfunction","Ventricular tachycardia","Atrial fibrillation"],"answer":2,"why":"Uploaded answer key: Ventricular tachycardia","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":40},{"id":"pharm-e2-user-cardio14-mcq-041","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #41","q":"Which conditions are categorized as bradyarrhythmias in the lecture?","options":["Atrial flutter and ventricular fibrillation","Sinus node dysfunction and AV conduction disturbances","Ventricular tachycardia and PVCs","Premature atrial contractions and atrial flutter"],"answer":1,"why":"Uploaded answer key: Sinus node dysfunction and AV conduction disturbances","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":41},{"id":"pharm-e2-user-cardio14-mcq-042","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #42","q":"What is the primary mechanism of Class I antiarrhythmic drugs?","options":["Beta-1 receptor blockade","Calcium channel activation","Increased myocardial refractory period through potassium channel activation exclusively","Inhibition of voltage-gated sodium channels"],"answer":3,"why":"Uploaded answer key: Inhibition of voltage-gated sodium channels","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":42},{"id":"pharm-e2-user-cardio14-mcq-043","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #43","q":"According to the lecture, which sodium channel states are targeted by Class I antiarrhythmics?","options":["Open and refractory channels","Closed channels exclusively","Potassium-bound channels exclusively","Calcium-dependent channels exclusively"],"answer":0,"why":"Class I antiarrhythmics have state-dependent affinity for cardiac sodium channels. Preferential interaction with activated/inactivated states can affect rapidly firing or depolarized tissue.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":43,"originalImportedWhy":"Uploaded answer key: Open and refractory channels","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-044","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #44","q":"What happens when a Class I antiarrhythmic dissociates from a sodium channel?","options":["The channel is permanently destroyed.","The drug is converted into calcium.","The drug may reassociate when the channel reopens or returns to a refractory state.","The channel becomes permanently insensitive to electrical activity."],"answer":2,"why":"Channel-binding and unbinding rates determine whether a drug continues to block channels between beats. Class IB agents dissociate rapidly; IC agents dissociate slowly and can markedly delay conduction.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":44,"originalImportedWhy":"Uploaded answer key: The drug may reassociate when the channel reopens or returns to a refractory state.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-045","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #45","q":"Which two Class I antiarrhythmics rapidly associate with and dissociate from sodium channels?","options":["Procainamide and flecainide","Lidocaine and mexiletine","Verapamil and diltiazem","Amiodarone and sotalol"],"answer":1,"why":"Uploaded answer key: Lidocaine and mexiletine","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":45},{"id":"pharm-e2-user-cardio14-mcq-046","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #46","q":"Which type of cardiac dysrhythmia is primarily treated with lidocaine and mexiletine?","options":["Atrial flutter exclusively","Atrial fibrillation exclusively","Sinus bradycardia","Ventricular dysrhythmias"],"answer":3,"why":"Uploaded answer key: Ventricular dysrhythmias","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":46},{"id":"pharm-e2-user-cardio14-mcq-047","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #47","q":"Which drug-route combination is appropriate according to the lecture?","options":["Lidocaine IV for severe acute ventricular arrhythmias","Lidocaine orally for chronic ventricular arrhythmias","Mexiletine IV exclusively for acute cardiac arrest","Flecainide topically for ventricular tachycardia"],"answer":0,"why":"Uploaded answer key: Lidocaine IV for severe acute ventricular arrhythmias","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":47},{"id":"pharm-e2-user-cardio14-mcq-048","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #48","q":"Which Class IB antiarrhythmic is administered orally for ongoing management of selected ventricular arrhythmias?","options":["Dobutamine","Amrinone","Mexiletine","Sodium nitroprusside"],"answer":2,"why":"Mexiletine is an orally active Class IB sodium-channel blocker related pharmacologically to lidocaine, which is commonly administered IV for acute serious ventricular arrhythmias. Its formulation varies by market and should not be memorized as universally supplied as an oral syrup.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":48,"originalImportedQuestion":"Which medication is available as an oral syrup for long-term management of ventricular arrhythmias?","originalImportedAnswer":"Mexiletine","originalImportedWhy":"Uploaded answer key: Mexiletine"},{"id":"pharm-e2-user-cardio14-mcq-049","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #49","q":"According to the lecture, lidocaine and mexiletine are contraindicated for which conditions?","options":["Ventricular tachycardia and PVCs","Atrial fibrillation and atrial flutter","Ventricular ectopic beats","Ventricular dysrhythmias"],"answer":1,"why":"Uploaded answer key: Atrial fibrillation and atrial flutter","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":49},{"id":"pharm-e2-user-cardio14-mcq-050","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #50","q":"Why can lidocaine also function as a local anesthetic?","options":["It stimulates muscarinic receptors.","It increases pain-transmitting nerve activity.","It activates sensory nerve calcium channels.","It blocks voltage-gated sodium channels in pain-transmitting neurons."],"answer":3,"why":"Local anesthetics such as lidocaine block neuronal voltage-gated sodium channels, preventing propagation of action potentials along nociceptive fibers. The same molecular target also acts in ventricular myocardium.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":50,"originalImportedWhy":"Uploaded answer key: It blocks voltage-gated sodium channels in pain-transmitting neurons.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-051","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #51","q":"What is the primary mechanism of action of procainamide?","options":["Voltage-gated sodium channel inhibition","PDE3 inhibition","Beta-1 receptor activation","Angiotensin II receptor blockade"],"answer":0,"why":"Uploaded answer key: Voltage-gated sodium channel inhibition","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":51},{"id":"pharm-e2-user-cardio14-mcq-052","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #52","q":"How does procainamide compare with lidocaine regarding sodium channel binding kinetics?","options":["Procainamide binds more rapidly than lidocaine.","Procainamide never dissociates.","Procainamide exhibits intermediate association and dissociation kinetics.","Procainamide exclusively binds calcium channels."],"answer":2,"why":"Procainamide has intermediate sodium-channel binding kinetics (Class IA), unlike the fast-unbinding Class IB agents lidocaine and mexiletine. This influences conduction slowing and proarrhythmia risk.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":52,"originalImportedWhy":"Uploaded answer key: Procainamide exhibits intermediate association and dissociation kinetics.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-053","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #53","q":"Which of the following Class I agents may be administered orally for selected ventricular arrhythmias but requires careful monitoring for conduction effects?","options":["Lidocaine","Procainamide","Dobutamine","Atropine"],"answer":1,"why":"Procainamide is a Class IA sodium-channel blocker that can be used for selected arrhythmias, although mexiletine and sotalol are also common alternatives depending on the patient. It should not be framed as universally preferred for every chronic ventricular tachyarrhythmia.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":53,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources.","originalImportedQuestion":"According to the lecture, which drug is preferred for long-term oral treatment of ventricular tachycardia and other ventricular arrhythmias?","originalImportedAnswer":"Procainamide","originalImportedWhy":"Uploaded answer key: Procainamide"},{"id":"pharm-e2-user-cardio14-mcq-054","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #54","q":"How should procainamide dosing be adjusted in patients with renal disease according to the lecture?","options":["Double the dose.","Increase administration frequency.","No adjustment is necessary.","Reduce the dose by approximately 50%."],"answer":3,"why":"Procainamide is cleared partly through renal pathways, so impaired renal function can increase exposure and proarrhythmic toxicity. The appropriate reduction depends on renal function and monitoring, not a universal 50% rule.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":54,"originalImportedWhy":"Uploaded answer key: Reduce the dose by approximately 50%.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-055","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #55","q":"Which condition is a contraindication for procainamide according to the lecture?","options":["Arrhythmias caused by conduction block","Ventricular tachycardia without conduction block","Premature ventricular contractions","Ventricular ectopic activity without conduction block"],"answer":0,"why":"Uploaded answer key: Arrhythmias caused by conduction block","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":55},{"id":"pharm-e2-user-cardio14-mcq-056","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #56","q":"Which Class I antiarrhythmic has slow sodium channel association and dissociation kinetics?","options":["Lidocaine","Mexiletine","Flecainide","Procainamide"],"answer":2,"why":"Uploaded answer key: Flecainide","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":56},{"id":"pharm-e2-user-cardio14-mcq-057","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #57","q":"What is an important precaution when considering flecainide for arrhythmias?","options":["It is preferred for every patient with structural heart disease.","It can be proarrhythmic, especially in patients with structural heart disease.","It has no effects on myocardial conduction.","It is used exclusively to treat bradycardia."],"answer":1,"why":"Flecainide is a Class IC sodium-channel blocker with slow dissociation that slows conduction and can cause proarrhythmia in susceptible patients. It can be used for some re-entry arrhythmias; the uploaded question's claim that re-entry dysrhythmias are excluded was misleading.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":57,"originalImportedQuestion":"According to the lecture, which dysrhythmia category is excluded from flecainide's listed indications?","originalImportedAnswer":"Re-entry dysrhythmias","originalImportedWhy":"Uploaded answer key: Re-entry dysrhythmias"},{"id":"pharm-e2-user-cardio14-mcq-058","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #58","q":"What is the primary mechanism of Class II antiarrhythmic drugs?","options":["Sodium channel blockade","PDE5 inhibition","Increased calcium sensitivity","Beta-adrenergic receptor antagonism"],"answer":3,"why":"Uploaded answer key: Beta-adrenergic receptor antagonism","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":58},{"id":"pharm-e2-user-cardio14-mcq-059","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #59","q":"How does beta-1 receptor antagonism help control cardiac arrhythmias?","options":["It reduces sympathetic-mediated myocardial excitation.","It increases myocardial electrical impulses.","It increases heart rate and contractility.","It activates ventricular sodium channels."],"answer":0,"why":"Beta-1 blockade reduces cAMP-mediated cardiac calcium signaling and slows sympathetic pacing/conduction. It can control some tachyarrhythmias, but reduced contractility or bradycardia can be harmful in susceptible patients.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":59,"originalImportedWhy":"Uploaded answer key: It reduces sympathetic-mediated myocardial excitation.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-060","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #60","q":"Which medication is described as the classic beta-blocker used in all three companion animal species?","options":["Amiodarone","Diltiazem","Propranolol","Lidocaine"],"answer":2,"why":"Uploaded answer key: Propranolol","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":60},{"id":"pharm-e2-user-cardio14-mcq-061","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #61","q":"A cat develops a tachyarrhythmia associated with hyperthyroidism. Which medication is identified as appropriate in the lecture?","options":["Amlodipine","Propranolol","Hydralazine","Sildenafil"],"answer":1,"why":"Hyperthyroidism increases metabolic demand and cardiac adrenergic responsiveness, contributing to tachycardia. A beta blocker such as propranolol can reduce rate and symptoms but does not correct excess thyroid-hormone synthesis.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":61,"originalImportedQuestion":"A cat develops a tachyarrhythmia associated with hyperthyroidism. Which medication is identified as appropriate in the lecture?","originalImportedAnswer":"Propranolol","originalImportedWhy":"Uploaded answer key: Propranolol"},{"id":"pharm-e2-user-cardio14-mcq-062","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #62","q":"Why should propranolol be titrated cautiously according to the lecture?","options":["It permanently inhibits sodium channels.","It causes excessive calcium sensitization.","It irreversibly inhibits PDE3.","Its nonselective beta blockade can inhibit beta-2-mediated bronchodilation and produce bronchospasm."],"answer":3,"why":"Propranolol blocks beta-1 and beta-2 receptors. Beta-2 blockade removes bronchodilating tone and may worsen reactive airway disease or bronchospasm.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":62,"originalImportedWhy":"Uploaded answer key: Its nonselective beta blockade can inhibit beta-2-mediated bronchodilation and produce bronchospasm.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-063","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #63","q":"Which beta-blocker is identified as another option for dogs?","options":["Sotalol","Digoxin","Pimobendan","Enalapril"],"answer":0,"why":"Uploaded answer key: Sotalol","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":63},{"id":"pharm-e2-user-cardio14-mcq-064","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #64","q":"What is the defining mechanism of Class III antiarrhythmic medications?","options":["Increasing sodium entry into myocytes","Increasing myocardial calcium sensitivity","Prolonging the myocardial refractory period","Directly stimulating beta-1 receptors"],"answer":2,"why":"Class III antiarrhythmics typically inhibit repolarizing potassium currents, prolonging the action potential and effective refractory period. This can interrupt re-entry but may prolong QT and cause proarrhythmia.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":64,"originalImportedWhy":"Uploaded answer key: Prolonging the myocardial refractory period","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-065","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #65","q":"Which drug is identified as a Class III antiarrhythmic?","options":["Mexiletine","Amiodarone","Procainamide","Diltiazem"],"answer":1,"why":"Uploaded answer key: Amiodarone","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":65},{"id":"pharm-e2-user-cardio14-mcq-066","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #66","q":"Which mechanism is associated with amiodarone?","options":["Selective PDE3 inhibition","Direct activation of beta-1 receptors","Exclusive sodium channel activation","Complex potassium and calcium channel blockade"],"answer":3,"why":"Amiodarone has multiple channel and adrenergic effects, but its potassium-channel effect prolongs repolarization. Tissue accumulation produces delayed, sometimes organ-specific toxicity.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":66,"originalImportedWhy":"Uploaded answer key: Complex potassium and calcium channel blockade","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-067","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #67","q":"Which patient would have a contraindication to amiodarone according to the lecture?","options":["A patient with bradycardia","A patient with ventricular tachycardia","A patient with supraventricular tachycardia","A patient with atrial arrhythmia without bradycardia"],"answer":0,"why":"Amiodarone slows cardiac conduction and can worsen bradycardia or conduction block. Potential pulmonary, liver and other toxicity also requires species-specific risk review.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":67,"originalImportedWhy":"Uploaded answer key: A patient with bradycardia","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-068","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #68","q":"Which adverse effects are associated with amiodarone?","options":["Hypokalemia and urinary retention exclusively","Severe hypoglycemia and renal glucosuria","Pulmonary fibrosis, gastrointestinal disturbances, and corneal deposits","Increased gastrointestinal motility without other effects"],"answer":2,"why":"Amiodarone accumulates in tissues and can cause pulmonary, hepatic, thyroid, ocular and other adverse effects. Monitor the species-specific risk profile and duration of therapy.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":68,"originalImportedWhy":"Uploaded answer key: Pulmonary fibrosis, gastrointestinal disturbances, and corneal deposits","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-069","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #69","q":"Which medications are classified as Class IV antiarrhythmics?","options":["Lidocaine and mexiletine","Verapamil and diltiazem","Propranolol and sotalol","Dopamine and dobutamine"],"answer":1,"why":"Uploaded answer key: Verapamil and diltiazem","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":69,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources."},{"id":"pharm-e2-user-cardio14-mcq-070","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #70","q":"Which drug-class statement correctly describes verapamil and diltiazem?","options":["Both are administered exclusively by inhalation.","Diltiazem is only used intravenously.","Both are beta-1 agonists.","Both are non-dihydropyridine calcium-channel blockers; route and duration depend on the formulation and clinical situation."],"answer":3,"why":"Both block L-type calcium channels, slowing AV nodal conduction; either may have oral or parenteral uses depending on formulation and patient. The original strict IV-verapamil/oral-diltiazem distinction is not generally reliable.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":70,"originalImportedQuestion":"According to the lecture, which statement correctly compares verapamil and diltiazem?","originalImportedAnswer":"Verapamil is given IV for short-term use, while diltiazem is given orally for long-term use.","originalImportedWhy":"Uploaded answer key: Verapamil is given IV for short-term use, while diltiazem is given orally for long-term use."},{"id":"pharm-e2-user-cardio14-mcq-071","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #71","q":"Which group of diseases is identified as potential causes of systemic hypertension?","options":["Hyperthyroidism, hyperadrenocorticism, renal disease, and diabetes","Hypothyroidism exclusively","Gastrointestinal parasitism and dermatophytosis","Otitis externa and allergic dermatitis"],"answer":0,"why":"Uploaded answer key: Hyperthyroidism, hyperadrenocorticism, renal disease, and diabetes","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":71},{"id":"pharm-e2-user-cardio14-mcq-072","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #72","q":"Which medication is identified as a front-line monotherapy for hypertension in cats?","options":["Propranolol","Digoxin","Amlodipine","Mexiletine"],"answer":2,"why":"Amlodipine blocks L-type calcium channels predominantly in vascular smooth muscle, decreasing arteriolar resistance and systemic blood pressure. Blood-pressure monitoring is vital because antihypertensive dosing depends on the patient.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":72,"originalImportedQuestion":"Which medication is identified as a front-line monotherapy for hypertension in cats?","originalImportedAnswer":"Amlodipine","originalImportedWhy":"Uploaded answer key: Amlodipine"},{"id":"pharm-e2-user-cardio14-mcq-073","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #73","q":"How does amlodipine reduce systemic blood pressure?","options":["Increasing intracellular calcium in vascular smooth muscle","Blocking calcium channels, reducing vascular smooth muscle contraction, and promoting vasodilation","Stimulating alpha-1 receptors","Increasing angiotensin II activity"],"answer":1,"why":"Vascular L-type calcium channel blockade limits smooth-muscle contraction, reducing systemic vascular resistance and blood pressure. Amlodipine's vascular selectivity makes it useful for feline systemic hypertension.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":73,"originalImportedWhy":"Uploaded answer key: Blocking calcium channels, reducing vascular smooth muscle contraction, and promoting vasodilation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-074","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #74","q":"A cat has hypertension associated with hyperthyroidism but does not have an arrhythmia. Which medication is preferred according to the lecture's study guide?","options":["Lidocaine","Amiodarone","Propranolol","Amlodipine"],"answer":3,"why":"Amlodipine lowers systemic vascular resistance and is commonly used for significant feline hypertension. A beta blocker may address tachyarrhythmia but is not an equivalent antihypertensive substitute; thyroid disease should also be treated.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":74,"originalImportedWhy":"Uploaded answer key: Amlodipine","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-075","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #75","q":"Which combination best describes the three mechanisms of hydralazine listed in the lecture?","options":["Reduced sarcoplasmic reticulum calcium release, increased nitric oxide sensitivity, and potassium channel opening","Increased calcium release, decreased nitric oxide activity, and sodium channel activation","PDE3 inhibition, troponin C sensitization, and beta-1 stimulation","Angiotensin II receptor blockade, PDE5 inhibition, and calcium channel activation"],"answer":0,"why":"Hydralazine directly relaxes arteriolar smooth muscle through several proposed pathways. The clinically important consequence is afterload reduction with possible hypotension and reflex tachycardia.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":75,"originalImportedWhy":"Uploaded answer key: Reduced sarcoplasmic reticulum calcium release, increased nitric oxide sensitivity, and potassium channel opening","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-076","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #76","q":"Why is hydralazine reserved for severe emergency-type hypertension according to the lecture?","options":["It causes permanent cardiac paralysis.","It increases angiotensin II production.","It can cause excessive hypotension, triggering baroreflex-mediated tachycardia.","It cannot relax vascular smooth muscle."],"answer":2,"why":"Excess arteriolar dilation can abruptly reduce blood pressure, triggering baroreflex tachycardia and impairing perfusion. Severe hypertension requires controlled monitoring rather than abrupt unmonitored reductions.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":76,"originalImportedWhy":"Uploaded answer key: It can cause excessive hypotension, triggering baroreflex-mediated tachycardia.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-077","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #77","q":"What is the primary mechanism of action of telmisartan?","options":["Beta-1 receptor antagonism","Angiotensin II receptor antagonism","Na⁺/K⁺ ATPase inhibition","PDE3 inhibition"],"answer":1,"why":"Uploaded answer key: Angiotensin II receptor antagonism","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":77,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources."},{"id":"pharm-e2-user-cardio14-mcq-078","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #78","q":"According to the lecture, which additional clinical indication is associated with telmisartan?","options":["Acute ventricular fibrillation","Bradyarrhythmia management","Local anesthesia","Reduction of nephropathy-associated proteinuria"],"answer":3,"why":"Uploaded answer key: Reduction of nephropathy-associated proteinuria","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":78},{"id":"pharm-e2-user-cardio14-mcq-079","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #79","q":"Which two medications are ACE inhibitors?","options":["Enalapril and benazepril","Amlodipine and hydralazine","Telmisartan and sildenafil","Propranolol and sotalol"],"answer":0,"why":"Uploaded answer key: Enalapril and benazepril","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":79,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources."},{"id":"pharm-e2-user-cardio14-mcq-080","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #80","q":"What reaction is normally catalyzed by angiotensin-converting enzyme?","options":["cAMP → AMP","GTP → cGMP","Angiotensin I → angiotensin II","Calcium → sodium"],"answer":2,"why":"Uploaded answer key: Angiotensin I → angiotensin II","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":80},{"id":"pharm-e2-user-cardio14-mcq-081","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #81","q":"How can ACE inhibitors assist in the management of CHF according to the lecture?","options":["By increasing aldosterone production","By reducing angiotensin II and aldosterone production, thereby reducing fluid load","By directly activating myocardial beta-1 receptors","By increasing vascular resistance"],"answer":1,"why":"Less angiotensin II means less vasoconstriction and aldosterone-dependent sodium retention, reducing congestion and afterload in some CHF patients. Monitor kidney function and potassium because RAAS also supports renal perfusion.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":81,"originalImportedWhy":"Uploaded answer key: By reducing angiotensin II and aldosterone production, thereby reducing fluid load","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-082","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #82","q":"Why might ACE inhibitors be combined with positive inotropic medications such as digoxin?","options":["To permanently inhibit cardiac contraction","To eliminate the need for cardiac monitoring","To increase circulating blood volume","To help reduce vascular pressure and fluid load while supporting improved cardiac output"],"answer":3,"why":"Inotropes improve contractile performance while ACE inhibitors reduce RAAS-mediated afterload and fluid retention. A patient may benefit from different mechanisms, but combinations require close kidney/BP/electrolyte monitoring.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":82,"reviewFlag":"Course-specific mechanism or clinical recommendation; retain original for exam use and verify against current clinical sources.","originalImportedWhy":"Uploaded answer key: To help reduce vascular pressure and fluid load while supporting improved cardiac output","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-083","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #83","q":"Which two drugs are specifically identified for hypertensive crises?","options":["Hydralazine and sodium nitroprusside","Digoxin and dobutamine","Propranolol and sotalol","Mexiletine and flecainide"],"answer":0,"why":"Uploaded answer key: Hydralazine and sodium nitroprusside","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":83},{"id":"pharm-e2-user-cardio14-mcq-084","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #84","q":"How does sodium nitroprusside produce vasodilation?","options":["By stimulating alpha-1 receptors","By inhibiting troponin C","By donating nitric oxide, which promotes vascular smooth muscle relaxation","By directly stimulating myocardial beta-1 receptors"],"answer":2,"why":"Sodium nitroprusside releases nitric oxide, stimulating soluble guanylate cyclase and increasing cGMP. This relaxes vascular smooth muscle rapidly, requiring intensive BP monitoring.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":84,"originalImportedWhy":"Uploaded answer key: By donating nitric oxide, which promotes vascular smooth muscle relaxation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-085","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #85","q":"Which medication is identified as a treatment for pulmonary hypertension?","options":["Procainamide","Sildenafil","Digoxin","Phenoxybenzamine"],"answer":1,"why":"Uploaded answer key: Sildenafil","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":85},{"id":"pharm-e2-user-cardio14-mcq-086","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #86","q":"What is the primary mechanism of action of sildenafil?","options":["PDE3 activation","Beta-1 receptor antagonism","Angiotensin II receptor activation","PDE5 inhibition"],"answer":3,"why":"Sildenafil inhibits phosphodiesterase type 5, reducing cGMP degradation. In pulmonary vascular smooth muscle, persistent cGMP-dependent signaling facilitates vasodilation and can decrease pulmonary vascular resistance.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":86,"originalImportedQuestion":"What is the primary mechanism of action of sildenafil?","originalImportedAnswer":"PDE5 inhibition","originalImportedWhy":"Uploaded answer key: PDE5 inhibition"},{"id":"pharm-e2-user-cardio14-mcq-087","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #87","q":"Which signaling pathway is associated with sildenafil-mediated vasodilation?","options":["Nitric oxide → guanylate cyclase → increased cGMP → protein kinase G → decreased intracellular calcium","Beta-1 activation → increased cAMP → increased myocardial calcium","Na⁺/K⁺ ATPase inhibition → increased intracellular sodium","Alpha-1 activation → vascular smooth muscle contraction"],"answer":0,"why":"NO stimulates guanylate cyclase, cGMP activates protein kinase G, and calcium-sensitive contraction decreases. PDE5 inhibition prolongs this relaxation pathway, especially in pulmonary vasculature.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":87,"originalImportedWhy":"Uploaded answer key: Nitric oxide → guanylate cyclase → increased cGMP → protein kinase G → decreased intracellular calcium","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-088","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #88","q":"What would occur if PDE5 activity were increased rather than inhibited?","options":["Intracellular cGMP would increase indefinitely.","Vascular smooth muscle would become permanently relaxed.","cGMP degradation would increase, reducing relaxation signaling.","Calcium would no longer influence vascular smooth muscle."],"answer":2,"why":"PDE5 degrades cGMP. Increasing PDE5 activity reduces available cGMP and weakens NO-mediated vascular smooth-muscle relaxation.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":88,"originalImportedWhy":"Uploaded answer key: cGMP degradation would increase, reducing relaxation signaling.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-089","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #89","q":"According to the lecture, which three physiologic goals are central to cardiac resuscitation?","options":["Increase urine output, stimulate digestion, and reduce blood glucose","Restore cardiac contraction, maintain vascular tone, and preserve cerebral blood flow","Produce prolonged myocardial paralysis, reduce vascular tone, and decrease cerebral perfusion","Eliminate all sympathetic activity and inhibit myocardial contraction"],"answer":1,"why":"High-quality chest compressions provide circulatory pressure for coronary and cerebral perfusion; epinephrine may improve vascular tone. Return of an effective rhythm, airway/ventilation and correcting reversible causes are integrated goals, not just giving an inotrope.","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":89,"originalImportedWhy":"Uploaded answer key: Restore cardiac contraction, maintain vascular tone, and preserve cerebral blood flow","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-cardio14-mcq-090","lecture":"Lecture 14","sourceGroup":"Lecture 14 · uploaded MCQ set","topic":"Cardiovascular Pharmacology · #90","q":"Which medication is identified as the mainstay drug for cardiac resuscitation?","options":["Atropine","Sodium bicarbonate","Calcium gluconate","Epinephrine"],"answer":3,"why":"Uploaded answer key: Epinephrine","source":"User-supplied Lecture 14 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":90}];const target=window.VPQ_PHARM_EXAM2_PDF_PRACTICE||(window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[]);const ids=new Set(target.map(x=>x.id));for(const q of bank){if(!ids.has(q.id)){target.push(q);ids.add(q.id)}}window.VPQ_PHARM_CARDIO14_UPLOADED_MCQ_COUNT=bank.length;})();
